   335→async function generateEnvFile(envVars: Record<string, string>): Promise<void> {
   336→  log.step(7, "Génération du fichier .env.local...");
   337→
   338→  const envPath = path.join(process.cwd(), ".env.local");
   339→  const templatePath = path.join(process.cwd(), ".env-template");
   340→
   341→  if (fs.existsSync(envPath)) {
   342→    const overwrite = await question(
   343→      ".env.local existe déjà. Écraser ? (o/n) ",
   344→    );
   345→    if (overwrite.toLowerCase() !== "o") {
   346→      log.info("Conservation du .env.local existant");
   347→      return;
   348→    }
   349→  }
   350→
   351→  if (fs.existsSync(templatePath)) {
   352→    let template = fs.readFileSync(templatePath, "utf-8");
   353→
   354→    // Remplacer les valeurs connues
   355→    for (const [key, value] of Object.entries(envVars)) {
   356→      const regex = new RegExp(`^${key}=.*$`, "m");
   357→      template = template.replace(regex, `${key}="${value}"`);
   358→    }
   359→
   360→    // Générer BETTER_AUTH_SECRET si vide
   361→    if (
   362→      !template.includes('BETTER_AUTH_SECRET="') ||
   363→      template.includes('BETTER_AUTH_SECRET=""')
   364→    ) {
   365→      const secret = execSync("openssl rand -base64 32", {
   366→        encoding: "utf-8",
   367→      }).trim();
   368→      template = template.replace(
   369→        /BETTER_AUTH_SECRET=.*/,
   370→        `BETTER_AUTH_SECRET="${secret}"`,
   371→      );
   372→    }
   373→
   374→    fs.writeFileSync(envPath, template);
   375→    log.success(".env.local généré depuis le template");
   376→  } else {
   377→    log.warn(".env-template non trouvé, création d'un .env.local minimal");
   378→    const minimal = Object.entries(envVars)
   379→      .map(([k, v]) => `${k}="${v}"`)
   380→      .join("\n");
   381→    fs.writeFileSync(envPath, minimal);
   382→  }
   383→}
